from (values
  ('toy-sword', 'swords', '{"pl":"Miecz zabawkowy","en":"Toy sword","uk":"Іграшковий меч","de":"Spielzeugschwert","cs":"Dětský meč","lt":"Žaislinis kardas","es":"Espada de juguete","fr":"Épée jouet","ru":"Игрушечный меч"}', 1999, 10, 3, true, false, 0),
